                style: fonts.regular16,
              ),
            ),
            const Spacer(),
            AlignTransition(
              alignment: _alignmentAnimation,
              child: ElevatedButton(
                onPressed: () => context.read<SettingsRepository>().setToken(null),
                child: Text(
                  loc.logout,
                  style: fonts.regular14.copyWith(color: context.colors.red),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}
